"use strict";
import { AnimatePresence, motion } from "framer-motion";
import { Flex, styled, useSporeColors } from "ui/src";
const StarBorderBottom = styled(Flex, {
  position: "absolute",
  width: "300%",
  height: "50%",
  opacity: 0.7,
  bottom: -12,
  right: "-250%",
  borderRadius: "$roundedFull",
  zIndex: 0
});
const StarBorderTop = styled(StarBorderBottom, {
  top: -12,
  left: "-250%",
  bottom: "unset",
  right: "unset"
});
export const StarBorderButton = ({
  as: Component = "button",
  className = "",
  color,
  speed = "5s",
  py = 12,
  px = 16,
  borderRadius = 32,
  disabled = false,
  children,
  style,
  ...rest
}) => {
  const colors = useSporeColors();
  const grBorder = color || colors.neutral1.val;
  return <Component className={`button-clear ${className}`}>
      <AnimatePresence>
        <motion.div
    transition={{ duration: 0.3, ease: "linear" }}
    whileTap={{ scale: 0.94 }}
    exit={{ scale: 1 }}
    style={{
      padding: "1px 0",
      display: "inline-block",
      overflow: "hidden",
      position: "relative",
      borderRadius: borderRadius - borderRadius / 2,
      // minus 50%
      ...style,
      cursor: disabled ? "not-allowed" : "pointer"
    }}
  >
          <StarBorderBottom
    className="border-gradient-bottom"
    style={{
      background: `radial-gradient(circle, ${grBorder}, transparent 10%)`,
      animationDuration: speed,
      display: disabled ? "none" : "block"
    }}
  />
          <StarBorderTop
    className="border-gradient-top"
    style={{
      background: `radial-gradient(circle, ${grBorder}, transparent 10%)`,
      animationDuration: speed,
      display: disabled ? "none" : "block"
    }}
  />
          <Flex
    disabled={disabled}
    py={py}
    px={px}
    borderWidth={2}
    borderColor={"$surface3"}
    borderRadius={borderRadius}
    backgroundColor={"$surface1"}
    opacity={disabled ? 0.5 : 1}
    position="relative"
    zIndex={1}
    transition="all 0.2s ease-in-out"
    hoverStyle={{
      borderColor: disabled ? "$surface3Hovered" : "$surface3",
      backgroundColor: disabled ? "$surface1" : "$slate"
    }}
    {...rest}
  >
            {children}
          </Flex>
        </motion.div>
      </AnimatePresence>
    </Component>;
};
