import { SearchType } from '@uniswap/client-search/dist/search/v1/api_pb'
import { useMemo } from 'react'
import {
  searchTokenToCurrencyInfo,
  useSearchTokensQuery as useSearchTokensRestQuery,
} from 'uniswap/src/data/rest/searchTokens'
import { useUserTokens } from 'uniswap/src/contexts/UserTokensContext'
import { GqlResult } from 'uniswap/src/data/types'
import { SUPPORTED_CHAIN_IDS, UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { NUMBER_OF_RESULTS_LONG } from 'uniswap/src/features/search/SearchModal/constants'
import { useTokenFromAddress } from 'uniswap/src/hooks/useTokenFromAddress'
import { isAddress } from 'utilities/src/addresses'

export function useSearchTokensRest({
  searchQuery,
  chainFilter,
  skip,
  size = NUMBER_OF_RESULTS_LONG,
}: {
  searchQuery: string | null
  chainFilter: UniverseChainId | null
  skip: boolean
  size?: number
}): GqlResult<CurrencyInfo[]> {
  const { userAddedTokens } = useUserTokens()
  const variables = useMemo(
    () => ({
      searchQuery: searchQuery ?? undefined,
      chainIds: chainFilter ? [chainFilter] : SUPPORTED_CHAIN_IDS,
      searchType: SearchType.TOKEN,
      page: 1,
      size,
    }),
    [searchQuery, chainFilter, size],
  )

  const { data, error, isPending, refetch } = useSearchTokensRestQuery({ 
    input: variables, 
    enabled: !skip,
    userAddedTokens
  })

  // Check if search query is a valid address for blockchain token lookup
  const isValidAddress = searchQuery ? isAddress(searchQuery) : false
  const targetChainId = chainFilter || UniverseChainId.Sepolia // Default to Abstract testnet if no chain filter

  // Fetch token from blockchain if searching by address
  const {
    data: blockchainToken,
    loading: blockchainLoading,
    error: blockchainError,
    isValidToken
  } = useTokenFromAddress(
    isValidAddress ? searchQuery : null,
    targetChainId
  )

  const formattedData = useMemo(() => {
    // Start with token list results
    let results: CurrencyInfo[] = []
    
    if (data && data.tokens) {
      results = data.tokens
        .map((token) => {
          return searchTokenToCurrencyInfo(token)
        })
        .filter((c): c is CurrencyInfo => Boolean(c))
    }


    // If searching by address and we found a valid blockchain token, add it to results
    if (isValidAddress && blockchainToken && isValidToken) {
      // Check if token is already in results to avoid duplicates
      const existingToken = results.find(
        token => token.currency.address.toLowerCase() === searchQuery!.toLowerCase()
      )
      
      if (!existingToken) {
        // Add blockchain token at the beginning since it's an exact address match
        results.unshift(blockchainToken)
      }
    }

    return results.length > 0 ? results : undefined
  }, [data, blockchainToken, isValidToken, isValidAddress, searchQuery])

  const loading = isPending || (isValidAddress && blockchainLoading)
  const combinedError = error || (isValidAddress && blockchainError) || undefined

  return useMemo(
    () => ({ 
      data: formattedData, 
      loading, 
      error: combinedError, 
      refetch: () => {
        refetch()
        // Note: blockchain token fetching will auto-refetch via React Query
        return Promise.resolve()
      }
    }),
    [formattedData, loading, combinedError, refetch],
  )
}
