import { memo, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { TokenSelectorList } from 'uniswap/src/components/TokenSelector/TokenSelectorList'
import { useTokenSectionsForEmptySearch } from 'uniswap/src/components/TokenSelector/hooks/useTokenSectionsForEmptySearch'
import { OnSelectCurrency } from 'uniswap/src/components/TokenSelector/types'
import { UniverseChainId } from 'uniswap/src/features/chains/types'

function _TokenSelectorEmptySearchList({
  activeAccountAddress,
  chainFilter,
  onSelectCurrency,
  excludeNativeTokens = false,
}: {
  activeAccountAddress?: string
  onSelectCurrency: OnSelectCurrency
  chainFilter: UniverseChainId | null
  excludeNativeTokens?: boolean
}): JSX.Element {
  const { t } = useTranslation()

  const {
    data: sections,
    loading,
    error,
    refetch,
  } = useTokenSectionsForEmptySearch({
    activeAccountAddress,
    chainFilter,
  })

  // Filter out native tokens if excludeNativeTokens is true
  const filteredSections = useMemo(() => {
    if (!excludeNativeTokens || !sections) {
      return sections
    }
    
    return sections.map(section => ({
      ...section,
      data: section.data.filter((item: any) => {
        // Check if it's a token option (not an array)
        if (!Array.isArray(item) && item?.currencyInfo?.currency) {
          const currency = item.currencyInfo.currency
          // Filter out native tokens (ETH)
          return !(currency.isNative || currency.symbol === 'ETH')
        }
        return true
      })
    })).filter(section => section.data.length > 0) // Remove empty sections
  }, [sections, excludeNativeTokens])

  return (
    <TokenSelectorList
      showTokenAddress
      errorText={t('token.selector.search.error')}
      hasError={Boolean(error)}
      loading={loading}
      refetch={refetch}
      sections={filteredSections}
      showTokenWarnings={true}
      onSelectCurrency={onSelectCurrency}
    />
  )
}

export const TokenSelectorEmptySearchList = memo(_TokenSelectorEmptySearchList)
