"use strict";
export class MulticallManager {
  constructor(multicall) {
    this.multicall = multicall;
  }
  /**
   * Execute multicall in batches to avoid RPC limits
   */
  async executeBatched(calls, batchSize = 100) {
    if (calls.length === 0) return [];
    const batches = this.chunk(calls, batchSize);
    const results = [];
    for (const batch of batches) {
      try {
        const [, batchResults] = await this.multicall.callStatic.aggregate(batch);
        results.push(...batchResults);
      } catch (error) {
        console.error("Multicall batch failed:", error);
        results.push(...new Array(batch.length).fill("0x"));
      }
    }
    return results;
  }
  /**
   * Execute single multicall batch
   */
  async execute(calls) {
    if (calls.length === 0) return [];
    const [, results] = await this.multicall.callStatic.aggregate(calls);
    return results;
  }
  /**
   * Execute multicall with tryAggregate - doesn't fail if individual calls fail
   * Returns results with '0x' for failed calls
   */
  async tryExecute(calls, from) {
    if (calls.length === 0) return [];
    const overrides = from ? { from } : {};
    const results = await this.multicall.callStatic.tryAggregate(false, calls, overrides);
    return results.map(
      (result) => result.success ? result.returnData : "0x"
    );
  }
  chunk(array, size) {
    const chunks = [];
    for (let i = 0; i < array.length; i += size) {
      chunks.push(array.slice(i, i + size));
    }
    return chunks;
  }
}
