"use strict";
import { BigNumber } from "@ethersproject/bignumber";
import { CurrencyAmount, Token } from "@uniswap/sdk-core";
import { Pool as V3Pool, Position as V3PositionSDK } from "@uniswap/v3-sdk";
import { Pair } from "@uniswap/v2-sdk";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import JSBI from "jsbi";
export class PositionFactory {
  /**
   * Create V2 Position from pool and balance data
   */
  static createV2Position({
    poolData,
    balance,
    claimable0,
    claimable1,
    chainId,
    walletAddress,
    gaugeData = null,
    isStaked = false,
    gaugeAddress
  }) {
    const { amount0, amount1 } = this.calculateV2Amounts(
      balance,
      poolData.totalSupply,
      poolData.reserve0,
      poolData.reserve1
    );
    const token0 = new Token(
      chainId,
      poolData.token0.id,
      parseInt(poolData.token0.decimals),
      poolData.token0.symbol,
      poolData.token0.name
    );
    const token1 = new Token(
      chainId,
      poolData.token1.id,
      parseInt(poolData.token1.decimals),
      poolData.token1.symbol,
      poolData.token1.name
    );
    const liquidityToken = new Token(chainId, poolData.id, 18, "LP", "Liquidity Provider Token");
    const currency0Amount = CurrencyAmount.fromRawAmount(token0, amount0);
    const currency1Amount = CurrencyAmount.fromRawAmount(token1, amount1);
    const pair = new Pair(currency0Amount, currency1Amount);
    const hasLiquidity = BigNumber.from(balance).gt(0);
    const positionStatus = hasLiquidity ? PositionStatus.IN_RANGE : PositionStatus.CLOSED;
    return {
      poolId: poolData.id,
      chainId,
      version: ProtocolVersion.V2,
      liquidity: balance,
      liquidityAmount: CurrencyAmount.fromRawAmount(liquidityToken, balance),
      status: positionStatus,
      currency0Amount,
      currency1Amount,
      liquidityToken,
      pair,
      feeTier: void 0,
      v4hook: void 0,
      owner: walletAddress,
      poolType: poolData.stable ? "stable" : "volatile",
      // Fee data
      token0UncollectedFees: claimable0,
      token1UncollectedFees: claimable1,
      // Gauge data - prefer direct parameters over gaugeData object
      isStaked: isStaked || gaugeData?.isStaked || false,
      gaugeAddress: gaugeAddress || gaugeData?.gaugeAddress || void 0,
      hasGaugeStake: isStaked || gaugeData?.hasGaugeStake || false,
      isGaugePosition: false
    };
  }
  /**
   * Create V3 Position from position data and pool data
   */
  static createV3Position({
    tokenId,
    positionData,
    poolData,
    chainId,
    walletAddress,
    feeData = { token0: "0", token1: "0" },
    gaugeData = null
  }) {
    const token0 = new Token(
      chainId,
      positionData[2],
      parseInt(poolData.token0.decimals),
      poolData.token0.symbol,
      poolData.token0.name
    );
    const token1 = new Token(
      chainId,
      positionData[3],
      parseInt(poolData.token1.decimals),
      poolData.token1.symbol,
      poolData.token1.name
    );
    const tickSpacing = parseInt(poolData.tickSpacing);
    const feeMap = { 1: 100, 50: 500, 100: 500, 200: 3e3, 2e3: 1e4 };
    const fee = feeMap[tickSpacing] || 3e3;
    const pool = new V3Pool(
      token0,
      token1,
      fee,
      JSBI.BigInt(poolData.sqrtPrice),
      JSBI.BigInt(poolData.liquidity),
      parseInt(poolData.tick)
    );
    const position = new V3PositionSDK({
      pool,
      liquidity: positionData[7].toString(),
      tickLower: positionData[5],
      tickUpper: positionData[6]
    });
    const hasLiquidity = BigNumber.from(positionData[7]).gt(0);
    const currentTick = parseInt(poolData.tick);
    const positionStatus = this.getV3PositionStatus(
      currentTick,
      positionData[5],
      positionData[6],
      hasLiquidity
    );
    return {
      poolId: poolData.id,
      chainId,
      tokenId,
      version: ProtocolVersion.V3,
      liquidity: positionData[7].toString(),
      tickLower: positionData[5].toString(),
      tickUpper: positionData[6].toString(),
      status: positionStatus,
      currency0Amount: position.amount0,
      currency1Amount: position.amount1,
      pool,
      position,
      feeTier: fee,
      tickSpacing,
      v4hook: void 0,
      owner: walletAddress,
      // Fee data
      token0UncollectedFees: feeData.token0,
      token1UncollectedFees: feeData.token1,
      // Gauge data
      isStaked: gaugeData?.isStaked || false,
      gaugeAddress: gaugeData?.gaugeAddress || void 0,
      hasGaugeStake: gaugeData?.hasGaugeStake || false,
      isGaugePosition: false
    };
  }
  /**
   * Calculate V2 position amounts from LP balance and reserves
   */
  static calculateV2Amounts(userBalance, totalSupply, reserve0, reserve1) {
    const parseDecimalString = (value) => {
      if (!value.includes(".")) {
        return BigNumber.from(value + "000000000000000000");
      }
      const [whole, decimal] = value.split(".");
      const paddedDecimal = decimal.padEnd(18, "0").substring(0, 18);
      return BigNumber.from(whole + paddedDecimal);
    };
    const userBN = BigNumber.from(userBalance);
    const totalBN = parseDecimalString(totalSupply);
    const reserve0BN = parseDecimalString(reserve0);
    const reserve1BN = parseDecimalString(reserve1);
    if (totalBN.eq(0)) return { amount0: "0", amount1: "0" };
    const amount0 = userBN.mul(reserve0BN).div(totalBN);
    const amount1 = userBN.mul(reserve1BN).div(totalBN);
    return { amount0: amount0.toString(), amount1: amount1.toString() };
  }
  /**
   * Determine V3 position status based on current tick vs position range
   */
  static getV3PositionStatus(currentTick, tickLower, tickUpper, hasLiquidity) {
    if (!hasLiquidity) {
      return PositionStatus.CLOSED;
    }
    if (currentTick >= tickLower && currentTick <= tickUpper) {
      return PositionStatus.IN_RANGE;
    } else {
      return PositionStatus.OUT_OF_RANGE;
    }
  }
}
