"use strict";
import { Contract } from "@ethersproject/contracts";
import { BigNumber } from "@ethersproject/bignumber";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import ERC20_ABI from "uniswap/src/abis/erc20.json";
import { PositionFactory } from "./PositionFactory";
const ABSTRACT_POOL_ABI = [
  {
    inputs: [],
    name: "index0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "index1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "supplyIndex1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable0",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ internalType: "address", name: "", type: "address" }],
    name: "claimable1",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "tokens",
    outputs: [{ internalType: "address", name: "", type: "address" }, { internalType: "address", name: "", type: "address" }],
    stateMutability: "view",
    type: "function"
  }
];
export class StakedV2PositionService {
  constructor(multicallManager, chainId, walletAddress, provider) {
    this.multicallManager = multicallManager;
    this.chainId = chainId;
    this.walletAddress = walletAddress;
    this.erc20Interface = new Contract("0x0000000000000000000000000000000000000000", ERC20_ABI, provider).interface;
    this.poolInterface = new Contract("0x0000000000000000000000000000000000000000", ABSTRACT_POOL_ABI, provider).interface;
  }
  erc20Interface;
  poolInterface;
  /**
   * Fetch staked V2 positions from gauge data
   */
  async fetchPositions(v2Pools, gaugeStakes, protocolVersions) {
    if (!this.shouldFetchStakedV2(v2Pools, gaugeStakes, protocolVersions)) {
      return [];
    }
    const v2PoolAddresses = new Set(v2Pools.map((pool) => pool.id.toLowerCase()));
    const stakedV2Positions = gaugeStakes.filter(
      (stake) => v2PoolAddresses.has(stake.gauge.pool.toLowerCase()) && stake.amount && stake.amount !== "0"
    );
    if (stakedV2Positions.length === 0) {
      return [];
    }
    const calls = this.buildStakedV2Calls(stakedV2Positions, v2Pools);
    const results = await this.multicallManager.executeBatched(calls, 70);
    return this.processStakedV2Results(results, stakedV2Positions, v2Pools);
  }
  shouldFetchStakedV2(v2Pools, gaugeStakes, protocolVersions) {
    return v2Pools.length > 0 && gaugeStakes.length > 0 && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V2));
  }
  /**
   * Build multicall data for staked V2 positions
   */
  buildStakedV2Calls(stakedPositions, v2Pools) {
    const calls = [];
    stakedPositions.forEach((stakedPosition) => {
      const poolAddress = stakedPosition.gauge.pool;
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("index0", [])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("index1", [])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("supplyIndex0", [this.walletAddress])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("supplyIndex1", [this.walletAddress])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("claimable0", [this.walletAddress])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("claimable1", [this.walletAddress])
      });
      calls.push({
        target: poolAddress,
        callData: this.poolInterface.encodeFunctionData("tokens", [])
      });
    });
    return calls;
  }
  /**
   * Process multicall results into staked V2 PositionInfo objects
   */
  processStakedV2Results(results, stakedPositions, v2Pools) {
    const positions = [];
    const callsPerPosition = 7;
    const poolMap = new Map(v2Pools.map((pool) => [pool.id.toLowerCase(), pool]));
    for (let i = 0; i < stakedPositions.length; i++) {
      const stakedPosition = stakedPositions[i];
      const resultOffset = i * callsPerPosition;
      try {
        if (resultOffset + callsPerPosition > results.length) {
          console.warn(`[STAKED V2] Insufficient results for staked position in pool ${stakedPosition.gauge.pool}`);
          continue;
        }
        const pool = poolMap.get(stakedPosition.gauge.pool.toLowerCase());
        if (!pool) {
          console.warn(`[STAKED V2] Pool data not found for ${stakedPosition.gauge.pool}`);
          continue;
        }
        const index0 = this.poolInterface.decodeFunctionResult("index0", results[resultOffset])[0];
        const index1 = this.poolInterface.decodeFunctionResult("index1", results[resultOffset + 1])[0];
        const supplyIndex0 = this.poolInterface.decodeFunctionResult("supplyIndex0", results[resultOffset + 2])[0];
        const supplyIndex1 = this.poolInterface.decodeFunctionResult("supplyIndex1", results[resultOffset + 3])[0];
        const claimable0 = this.poolInterface.decodeFunctionResult("claimable0", results[resultOffset + 4])[0];
        const claimable1 = this.poolInterface.decodeFunctionResult("claimable1", results[resultOffset + 5])[0];
        const balance = stakedPosition.amount;
        let pendingFees0 = "0";
        let pendingFees1 = "0";
        try {
          if (supplyIndex0.gt(0) && index0.gt(supplyIndex0)) {
            const indexDiff0 = index0.sub(supplyIndex0);
            const stakedBalanceBN = BigNumber.from(balance);
            pendingFees0 = stakedBalanceBN.mul(indexDiff0).div("1000000000000000000").toString();
          }
          if (supplyIndex1.gt(0) && index1.gt(supplyIndex1)) {
            const indexDiff1 = index1.sub(supplyIndex1);
            const stakedBalanceBN = BigNumber.from(balance);
            pendingFees1 = stakedBalanceBN.mul(indexDiff1).div("1000000000000000000").toString();
          }
        } catch (e) {
          console.warn(`[STAKED V2] Fee calculation failed for staked position in pool ${pool.id}:`, e);
        }
        const totalFees0 = claimable0.add(pendingFees0 || "0").toString();
        const totalFees1 = claimable1.add(pendingFees1 || "0").toString();
        const position = PositionFactory.createV2Position({
          poolData: pool,
          balance,
          // This is the staked amount
          claimable0: totalFees0,
          claimable1: totalFees1,
          chainId: this.chainId,
          walletAddress: this.walletAddress,
          // Mark as staked
          isStaked: true,
          gaugeAddress: stakedPosition.gauge.id
        });
        positions.push(position);
      } catch (error) {
        console.error(`[STAKED V2] Failed to process staked position in pool ${stakedPosition.gauge.pool}:`, error);
      }
    }
    return positions;
  }
}
